#!/usr/bin/env python3
"""
E11 — Watershed com máscara causal congelada.

A máscara é calculada pela imagem e, opcionalmente, ampliada SOMENTE
pelos volumes passados por --mask-marker. Todos os métodos são então
executados sobre exatamente a mesma máscara e a mesma superfície -EDT.

Marcadores fora da máscara são removidos antes da renumeração. Os
marcadores normalizados efetivamente usados são salvos para a avaliação.
Não aceita GT.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
from pathlib import Path

import numpy as np
import pandas as pd
import tifffile
from scipy import ndimage as ndi
from skimage.filters import threshold_otsu
from skimage.segmentation import watershed


CONNECTIVITY_6 = ndi.generate_binary_structure(3, 1)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--image", type=Path, required=True)
    parser.add_argument(
        "--marker",
        action="append",
        required=True,
        metavar="LABEL=TIFF",
    )
    parser.add_argument(
        "--mask-marker",
        action="append",
        default=[],
        metavar="TIFF",
        help=(
            "Somente estes marcadores ampliam a máscara Otsu. "
            "Repita a opção quando necessário."
        ),
    )
    parser.add_argument(
        "--outside-policy",
        choices=("drop", "error"),
        default="drop",
    )
    parser.add_argument("--out-dir", type=Path, required=True)
    # batos_v3 patch: hard-coded mask constants exposed (defaults = frozen values)
    parser.add_argument("--v3-min-component", type=int, default=500)
    parser.add_argument("--v3-closing-iterations", type=int, default=1)
    return parser.parse_args()


def normalize_name(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", text.lower()).strip("_")


def read3d(path: Path, description: str) -> np.ndarray:
    if not path.is_file():
        raise FileNotFoundError(f"{description}: {path}")
    array = np.asarray(tifffile.imread(path))
    array = np.squeeze(array)
    if array.ndim == 4 and array.shape[-1] in (3, 4):
        array = array[..., 0]
    if array.ndim != 3:
        raise ValueError(
            f"{description} precisa ser 3D; shape={array.shape}"
        )
    return array


def sha256_array(array: np.ndarray) -> str:
    contiguous = np.ascontiguousarray(array)
    return hashlib.sha256(contiguous.view(np.uint8)).hexdigest()


def normalize_image(image: np.ndarray) -> np.ndarray:
    work = image.astype(np.float32, copy=False)
    finite = np.isfinite(work)
    if not finite.any():
        raise ValueError("Imagem sem valores finitos.")
    values = work[finite]
    low, high = np.percentile(values, [1.0, 99.0])
    if high <= low:
        low = float(values.min())
        high = float(values.max())
    if high <= low:
        return np.zeros(work.shape, dtype=np.float32)
    result = np.clip((work - low) / (high - low), 0.0, 1.0)
    result[~finite] = 0.0
    return result.astype(np.float32, copy=False)


def normalize01(array: np.ndarray, mask: np.ndarray) -> np.ndarray:
    values = array[mask & np.isfinite(array)]
    if values.size == 0:
        return np.zeros(array.shape, dtype=np.float32)
    low, high = np.percentile(values, [1.0, 99.0])
    if high <= low:
        low = float(values.min())
        high = float(values.max())
    if high <= low:
        return np.zeros(array.shape, dtype=np.float32)
    result = np.clip((array - low) / (high - low), 0.0, 1.0)
    result[~np.isfinite(result)] = 0.0
    return result.astype(np.float32, copy=False)


def clean_bright_otsu_mask(
    image_norm: np.ndarray,
    min_component: int = 500,
    closing_iterations: int = 1,
) -> tuple[np.ndarray, float]:
    threshold = float(threshold_otsu(image_norm))
    mask = image_norm > threshold
    mask = ndi.binary_closing(
        mask,
        structure=CONNECTIVITY_6,
        iterations=int(closing_iterations),
    )
    mask = ndi.binary_fill_holes(mask)
    labels, count = ndi.label(mask, structure=CONNECTIVITY_6)
    if count == 0:
        raise RuntimeError("A máscara Otsu bright ficou vazia.")
    sizes = np.bincount(labels.ravel())
    keep = sizes >= int(min_component)
    keep[0] = False
    return keep[labels], threshold


def parse_markers(
    values: list[str],
) -> dict[str, Path]:
    result: dict[str, Path] = {}
    for raw in values:
        label, separator, value = raw.partition("=")
        if not separator:
            raise ValueError(
                f"Marcador inválido '{raw}'. Use LABEL=TIFF."
            )
        label = normalize_name(label)
        path = Path(value).expanduser().resolve()
        if not path.is_file():
            raise FileNotFoundError(path)
        if label in result:
            raise ValueError(f"Rótulo duplicado: {label}")
        result[label] = path
    return result


def normalize_markers_in_mask(
    raw: np.ndarray,
    shape: tuple[int, int, int],
    mask: np.ndarray,
    outside_policy: str,
) -> tuple[np.ndarray, int]:
    if raw.shape != shape:
        raise ValueError(
            f"Shape do marcador {raw.shape} diferente de {shape}"
        )
    positive = raw > 0
    outside = positive & ~mask
    outside_count = int(outside.sum())
    if outside_count and outside_policy == "error":
        raise ValueError(
            f"{outside_count} voxels de marcador fora da máscara."
        )
    positive &= mask
    labels, count = ndi.label(
        positive,
        structure=CONNECTIVITY_6,
    )
    if count == 0:
        raise ValueError(
            "Volume de marcadores ficou vazio após aplicar a máscara."
        )
    return labels.astype(np.int32, copy=False), outside_count


def main() -> int:
    args = parse_args()
    image_path = args.image.expanduser().resolve()
    out_dir = args.out_dir.expanduser().resolve()
    segmentations_dir = out_dir / "segmentations"
    normalized_marker_dir = out_dir / "normalized_markers"
    out_dir.mkdir(parents=True, exist_ok=True)
    segmentations_dir.mkdir(exist_ok=True)
    normalized_marker_dir.mkdir(exist_ok=True)

    marker_paths = parse_markers(args.marker)
    image_raw = read3d(image_path, "Imagem")
    image_norm = normalize_image(image_raw)
    mask, otsu_threshold = clean_bright_otsu_mask(image_norm, args.v3_min_component, args.v3_closing_iterations)

    mask_marker_paths = [
        Path(value).expanduser().resolve()
        for value in args.mask_marker
    ]
    for path in mask_marker_paths:
        raw = read3d(path, "Mask marker")
        if raw.shape != image_raw.shape:
            raise ValueError(
                f"Mask marker shape={raw.shape}; image={image_raw.shape}"
            )
        mask |= raw > 0

    if not mask.any():
        raise RuntimeError("Máscara causal final vazia.")

    distance = ndi.distance_transform_edt(mask)
    surface = -normalize01(distance, mask)
    tifffile.imwrite(
        out_dir / "frozen_mask_uint8.tif",
        mask.astype(np.uint8),
        compression="zlib",
    )
    tifffile.imwrite(
        out_dir / "negative_edt_float32.tif",
        surface.astype(np.float32),
        compression="zlib",
    )

    rows: list[dict[str, object]] = []
    for label, path in marker_paths.items():
        raw = read3d(path, f"Marcadores {label}")
        markers, outside_count = normalize_markers_in_mask(
            raw,
            image_raw.shape,
            mask,
            args.outside_policy,
        )
        normalized_path = normalized_marker_dir / f"{label}.tif"
        tifffile.imwrite(
            normalized_path,
            markers,
            compression="zlib",
        )
        prediction = watershed(
            surface,
            markers=markers,
            connectivity=1,
            mask=mask,
            watershed_line=False,
        ).astype(np.int32, copy=False)
        segmentation_path = segmentations_dir / f"{label}_distance_c1.tif"
        tifffile.imwrite(
            segmentation_path,
            prediction,
            compression="zlib",
        )
        rows.append(
            {
                "configuration": f"{label}_distance_c1",
                "marker_source": label,
                "surface": "distance",
                "connectivity": 1,
                "marker_count": int(markers.max()),
                "marker_voxels_outside_frozen_mask": outside_count,
                "prediction_count": int(prediction.max()),
                "normalized_marker": str(normalized_path),
                "segmentation": str(segmentation_path),
                "marker_array_sha256": sha256_array(markers),
                "segmentation_array_sha256": sha256_array(prediction),
            }
        )
        print(
            f"[E11] {label}: markers={int(markers.max())} "
            f"outside_dropped={outside_count}"
        )

    frame = pd.DataFrame(rows)
    frame.to_csv(out_dir / "watershed_results.csv", index=False)
    manifest = {
        "experiment": "E11_fixed_mask_watershed",
        "gt_used": False,
        "image": str(image_path),
        "mask_marker_paths": [str(p) for p in mask_marker_paths],
        "otsu_threshold": float(otsu_threshold),
        "mask_fraction": float(mask.mean()),
        "mask_array_sha256": sha256_array(mask.astype(np.uint8)),
        "surface_array_sha256": sha256_array(surface),
        "outside_policy": args.outside_policy,
        "methods": rows,
    }
    (out_dir / "fixed_mask_manifest.json").write_text(
        json.dumps(manifest, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )
    print(frame.to_string(index=False))
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(
            f"[E11][ERRO] {type(exc).__name__}: {exc}",
            file=sys.stderr,
        )
        raise
